637	                        <div class="field-error" id="email-error"></div>
638	                    </div>
639	                    <div class="form-group">
640	                        <label for="message" class="required">Message <span>(10-1000 characters)</span></label>
641	                        <textarea id="message" name="message" placeholder="Tell us what you think..." required aria-required="true" aria-describedby="message-error message-counter" minlength="10" maxlength="1000"></textarea>
642	                        <div class="field-error" id="message-error"></div>
643	                        <div id="message-counter" class="message-counter">0 / 1000</div>
