684	
685	            const menuToggle = document.querySelector('.menu-toggle');
686	            const navMenu = document.getElementById('nav-menu');
687	
688	            if (menuToggle) {
689	                const closeMenu = () => {
690	                    menuToggle.setAttribute('aria-expanded', 'false');
691	                    navMenu.setAttribute('hidden', '');
692	                    menuToggle.focus();
693	                };
694	
695	                menuToggle.addEventListener('click', function() {
696	                    const isExpanded = menuToggle.getAttribute('aria-expanded') === 'true';
697	                    menuToggle.setAttribute('aria-expanded', !isExpanded);
698	                    navMenu.toggleAttribute('hidden');
699	                });
700	
701	                document.addEventListener('keydown', (e) => {
702	                    if (e.key === 'Escape' && menuToggle.getAttribute('aria-expanded') === 'true') {
703	                        closeMenu();
704	                    }
705	                });
706	
707	                const navLinks = navMenu.querySelectorAll('a');
708	                navLinks.forEach(link => {
709	                    link.addEventListener('click', closeMenu);
710	                });
711	            }
